
/* 外壳(底色/圆角/阴影)在 global.css 的 .界卡 上, 三个块共用。
   这里只管诊所块自己的排版。 */
.诊所 {
  &__招牌 {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 9px;
  }

  &__名 {
    color: #eef3f8;
    font-weight: 600;
    font-size: 1.06em;
    letter-spacing: 0.03em;
  }

  &__星 {
    color: #7fe3ff;
    font-size: 0.82em;
    white-space: nowrap;
  }

  &__行 {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 5px;
  }

  &__槽 {
    flex: 1;
    height: 6px;
    border-radius: 3px;
    background: rgba(255, 255, 255, 0.07);
    overflow: hidden;

    i {
      display: block;
      height: 100%;
      border-radius: 3px;
      transition: width 0.45s ease;

      &.is-名声 {
        background: linear-gradient(90deg, #4a7fa5, #7fe3ff);
      }

      &.is-精神 {
        background: linear-gradient(90deg, #6b5fa8, #b39ddb);
      }
    }
  }

  &__值 {
    color: #7d8896;
    font-size: 0.8em;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  &__条 {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 12px;
    margin: 8px 0 2px;
    padding-top: 8px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    color: #9aa5b1;
    font-size: 0.85em;
  }

  &__钱 {
    color: #ffd76e;
  }

  &__档 {
    color: #7fd6a0;
  }

  &__设 {
    color: #6f7a87;
    margin-left: auto;
  }

  /* 地点比别的「设」重要一点: 它是这一页唯一告诉玩家「我现在在哪」的字。
     但也不能亮到抢名声/精神力那两条 —— 所以只提一档灰。 */
  &__地 {
    color: #8c98a6;
  }

  /* ── 占卜入口 ──────────────────────────────────────────────────
     紫色系, 跟诊所页的蓝(名声/精神力)拉开 —— 它是这一页唯一的「非数据」
     动作, 长得不一样是对的。 */
  &__卜 {
    margin-top: 14px;
  }

  &__卜钮 {
    width: 100%;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    padding: 11px 14px;
    border-radius: 8px;
    border: 1px solid rgba(198, 168, 255, 0.3);
    background: linear-gradient(180deg, rgba(198, 168, 255, 0.13), rgba(198, 168, 255, 0.05));
    color: #d9c9ff;
    font-family: inherit;
    cursor: pointer;

    &:disabled {
      opacity: 0.45;
      cursor: default;
      border-color: rgba(255, 255, 255, 0.09);
      color: #6f7a87;
    }
  }

  &__卜题 {
    font-size: 0.94em;
    letter-spacing: 0.18em;
  }

  &__卜注 {
    font-size: 0.74em;
    opacity: 0.7;
  }
}

/* ── 占卜 ────────────────────────────────────────────────────────
   下面这一整段 (接管层 + 翻牌) 是 2026-10-05 从 世界/App.vue 整段搬来的,
   只改了外层类名的前缀。留着原来那些注释 —— 每一条都是被真实故障咬出来的。

   翻牌用的是 3D transform 而不是换两张图: 一句 transform 就有真正的翻面,
   而且牌背牌面都留在 DOM 里, 翻到一半也看得见两面的交界。

   `.卜牌__面` 必须 backface-visibility: hidden —— 少了它, 背面那层会透过
   正面显出来, 牌面上就是「愚者」和「✦」叠在一起。 */

/* 占卜接管整个面板时的那一屏。**不是浮层** —— 它就在正常流里, 顶掉诊所
   那几行 (见模板顶上的注释: 卡片是等高的 iframe, 卡片坐标系里没有「视口」
   这个概念, 浮层的内容会落在玩家看不见的地方)。

   底色就用 .界卡 自己的深色, 不再叠一层: 既然那一屏只有牌和解读,
   就没有「别让玩家看见下面」这件事要做。 */
.卜层 {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 10px 0 4px;
  min-height: 320px;
  justify-content: center;

  &__提 {
    margin: 0;
    font-size: 0.78em;
    letter-spacing: 0.24em;
    color: #9aa5b1;
  }

  &__解 {
    margin: 0;
    font-family: Georgia, 'Songti SC', 'SimSun', 'Noto Serif CJK SC', serif;
    font-size: 0.86em;
    line-height: 1.85;
    color: #ded4c4;
    text-align: justify;

    &--空 {
      color: #7b848f;
      text-align: center;
    }
  }

  &__关 {
    padding: 8px 18px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 7px;
    background: transparent;
    color: #9aa5b1;
    font-family: inherit;
    font-size: 0.82em;
    cursor: pointer;
  }
}

.卜牌 {
  position: relative;
  width: 128px;
  height: 208px;
  cursor: pointer;
  perspective: 900px;
  transition: transform 0.25s ease;

  &:active {
    transform: scale(0.98);
  }

  &__面 {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    border-radius: 9px;
    backface-visibility: hidden;
    transition: transform 0.62s cubic-bezier(0.4, 0.1, 0.2, 1);
  }

  &__背 {
    border: 1px solid rgba(198, 168, 255, 0.35);
    background:
      repeating-linear-gradient(45deg, rgba(198, 168, 255, 0.09) 0 5px, transparent 5px 10px),
      linear-gradient(160deg, #1d2333, #131824);
  }

  &__纹 {
    font-size: 1.7em;
    color: rgba(198, 168, 255, 0.6);
  }

  &__正 {
    transform: rotateY(180deg);
    border: 1px solid rgba(214, 190, 140, 0.42);
    background: linear-gradient(165deg, #f0e7d6, #ddd0b6);
    color: #2b2620;
    font-family: Georgia, 'Songti SC', 'SimSun', 'Noto Serif CJK SC', serif;
  }

  &__号 {
    font-size: 0.78em;
    letter-spacing: 0.12em;
    opacity: 0.62;
  }

  &__名 {
    font-size: 1.32em;
    letter-spacing: 0.1em;
  }

  &__逆 {
    margin-top: 2px;
    padding: 1px 7px;
    border: 1px solid rgba(150, 60, 60, 0.4);
    border-radius: 999px;
    font-size: 0.66em;
    letter-spacing: 0.16em;
    color: #8c3b3b;
  }

  /* 翻面。**两个面各写各的终点角, 不能合成一条 `.卜牌__面` 的规则** ——
     正面本来就起始于 180deg (见上面的 `&__正`), 一条通吃的 rotateY(180deg)
     会把它按在 180deg 不动, 于是翻完之后两个面**都**背朝外、都进了
     backface-visibility 的黑洞, 牌整个消失 (解读文字还在, 所以看起来只像
     「牌没画出来」)。正面要转到 360deg, 从 180 一路转过去, 动画是连的。

     逆位时正面再倒过来 180° —— 那是塔罗里「逆位」的字面意思, 比旁边那行
     「逆位」两个字更早被眼睛认出来 (那行也留着, 给不认识塔罗的人看)。

     `perspective` 挂在 .卜牌 上、`backface-visibility` 挂在面上: 反过来放
     的话每个面各自算透视, 翻起来像两张纸片各转各的, 不像一张牌在翻。 */
  &.is-翻 .卜牌__背 {
    transform: rotateY(180deg);
  }

  &.is-翻 .卜牌__正 {
    transform: rotateY(360deg);
  }

  &.is-翻.is-逆 .卜牌__正 {
    transform: rotateY(360deg) rotate(180deg);
  }
}
