
.申请块 {
  &__日 {
    margin: 0 0 7px;
    color: #6f7a87;
    font-size: 0.8em;
    font-weight: 500;
    letter-spacing: 0.08em;
  }

  &__空 {
    margin: 0 0 6px;
    color: #55606d;
    font-size: 0.85em;
  }

  &__已接 {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    padding-top: 9px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
  }

  &__已接标 {
    color: #6f7a87;
    font-size: 0.78em;
  }

  &__徽 {
    padding: 2px 8px;
    border-radius: 999px;
    background: rgba(127, 227, 255, 0.1);
    border: 1px solid rgba(127, 227, 255, 0.22);
    color: #a8ecff;
    font-size: 0.78em;
  }

  /* 掷完但 AI 还没起名的那些。虚框 + 压暗, 一眼看出「还不能接」——
     它们不在 申请列表 里, 所以点不动, 是这一局的待办而不是这一屏的病人 (spec §8.2) */
  &__待登 {
    margin: 8px 0;
    padding: 8px;
    border: 1px dashed currentColor;
    border-radius: 6px;
    opacity: 0.55;
  }

  &__待登标 {
    margin: 0 0 6px;
    font-size: 12px;
  }

  /* 治疗浮层。Teleport 到 body, 所以 fixed 是相对视口的 —— 盖住整个界面 */
  &__罩 {
    position: fixed;
    inset: 0;
    z-index: 9999;
  }
}

.申请 {
  padding: 9px 11px;
  margin-bottom: 7px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.055);

  &__首 {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 4px 9px;
  }

  &__名 {
    color: #eef3f8;
    font-weight: 600;
  }

  &__级 {
    color: #b39ddb;
    font-size: 0.85em;
  }

  &__熟 {
    padding: 1px 7px;
    border-radius: 999px;
    background: rgba(255, 215, 110, 0.1);
    border: 1px solid rgba(255, 215, 110, 0.24);
    color: #ffd76e;
    font-size: 0.76em;
  }

  &__污 {
    margin-left: auto;
    color: #7d8896;
    font-size: 0.85em;
    font-variant-numeric: tabular-nums;
  }

  &__源 {
    margin: 4px 0 7px;
    color: #77828f;
    font-size: 0.84em;
  }

  &__底 {
    display: flex;
    align-items: center;
    gap: 7px;
  }

  &__计 {
    flex: 1;
    color: #6f7a87;
    font-size: 0.8em;
    min-width: 0;
  }

  /* 床位满了。接诊按钮置灰时在旁边说明原因 ——
     只置灰不说话, 玩家会以为是坏了 (spec §5.2) */
  &__满 {
    margin-left: auto;
    font-size: 11px;
    opacity: 0.6;
  }

  &__钮 {
    flex: none;
    min-height: 30px;
    padding: 0 13px;
    border-radius: 7px;
    border: 1px solid transparent;
    font-family: inherit;
    font-size: 0.84em;
    cursor: pointer;
    transition: background 0.18s ease;

    &:disabled {
      opacity: 0.35;
      cursor: not-allowed;
    }

    &.is-接 {
      background: rgba(127, 227, 255, 0.15);
      border-color: rgba(127, 227, 255, 0.36);
      color: #a8ecff;

      /* 置灰的按钮别再亮起来 —— 否则「没床了」的按钮看着像能点 */
      &:not(:disabled):hover {
        background: rgba(127, 227, 255, 0.25);
      }
    }

    &.is-拒 {
      background: rgba(255, 255, 255, 0.045);
      border-color: rgba(255, 255, 255, 0.08);
      color: #77828f;

      &:not(:disabled):hover {
        background: rgba(255, 255, 255, 0.08);
      }
    }
  }
}

@media (max-width: 480px) {
  .申请__钮 {
    min-height: 34px;
    padding: 0 15px;
  }
}
